package simu.manufacturing;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.sql.*;
import java.time.Instant;
import java.util.*;
import static simu.manufacturing.Store.*;

/** Native receiving transactions only; the adapter never owns physical stock. */
final class Custody {
 static final class Capacity extends RuntimeException {Capacity(String message){super(message);}}
 static void complete(JsonNode value,String...fields){Policy.fields(value,fields);for(var field:fields)if(!value.has(field))throw new IllegalArgumentException("Complete custody object required: "+field);}
 static JsonNode location(JsonNode id,String owner,String category){if(id==null||!id.isTextual())throw new IllegalArgumentException("Physical endpoint required");for(var row:HandlingUnits.CATALOG.path("locations"))if(row.path("id").equals(id)&&row.path("owner").asText().equals(owner)){for(var kind:row.path("compatible"))if(kind.asText().equals(category))return row;}throw new Conflict("Unknown or incompatible custody endpoint");}
 static ObjectNode validate(JsonNode event){
  var header=(ObjectNode)event.deepCopy();header.put("type","sample.completed.v1");header.set("payload",Json.parse("{\"quantity\":1}"));Policy.envelope(header);
  var h=event.path("payload");complete(h,"id","run_id","epoch","source","destination_owner","origin","destination","state","unit","departure_token","receipt_id","reason");for(var field:List.of("id","run_id","epoch"))Policy.uuid(h.get(field));
  var unit=h.path("unit");complete(unit,"id","barcode","run_id","epoch","contents","category","state","owner","version","custody_generation","last_sequence","position","origin","destination","handoff_id");UUID id=Policy.uuid(unit.get("id"));
  if(!unit.path("contents").isArray()||unit.path("contents").size()!=1)throw new IllegalArgumentException("One complete SKU per native unit required");var item=unit.path("contents").get(0);complete(item,"sku","quantity");Production.code(item.get("sku"));Policy.integer(item.get("quantity"),1,10000);
  if(!h.path("source").asText().equals("storage")||!h.path("destination_owner").asText().equals("manufacturing")||!unit.path("owner").equals(h.path("source"))||!unit.path("category").asText().equals("raw"))throw new Conflict("Raw materials require Storage custody authority");
  location(h.get("origin"),"storage","raw");if(!location(h.get("destination"),"manufacturing","raw").path("kind").asText().equals("cell_input"))throw new Conflict("Raw custody requires a production input endpoint");
  int version=Policy.integer(unit.get("version"),1,Integer.MAX_VALUE),sequence=Policy.integer(unit.get("last_sequence"),0,Integer.MAX_VALUE),generation=Policy.integer(unit.get("custody_generation"),0,Integer.MAX_VALUE);
  if(!unit.path("barcode").asText().equals("HU-"+id.toString().replace("-","").toUpperCase(Locale.ROOT))||!unit.path("run_id").equals(h.path("run_id"))||!unit.path("epoch").equals(h.path("epoch")))throw new Conflict("Whole-unit identity or scope mismatch");
  String state=h.path("state").asText();if(!event.path("type").asText().equals("handling."+state+".v1")||!event.path("source").equals(h.path("source"))||!event.path("destination").equals(h.path("destination_owner"))||!event.path("boundary").asText().equals("materials")||!event.path("run_id").equals(h.path("run_id"))||!event.path("epoch").equals(h.path("epoch"))||!event.path("aggregate_id").equals(h.path("id"))||!event.path("causation_id").equals(h.path("id"))||event.path("aggregate_version").asInt()!=version)throw new Conflict("Custody envelope metadata mismatch");
  if(!h.path("reason").isNull()&&!h.path("reason").isTextual())throw new IllegalArgumentException("Custody reason must be text or null");
  if(state.equals("offered")){
   if(version>Integer.MAX_VALUE-2||sequence>Integer.MAX_VALUE-2||generation>Integer.MAX_VALUE-1)throw new Conflict("Custody counters lack departure and receipt headroom");
   if(!unit.path("state").asText().equals("reserved")||!unit.path("position").equals(h.path("origin"))||!unit.path("origin").isNull()||!unit.path("destination").isNull()||!unit.path("handoff_id").isNull()||!h.path("departure_token").isNull()||!h.path("receipt_id").isNull())throw new Conflict("Offer requires confirmed reserved source placement");
  }else if(Set.of("departed","acknowledged").contains(state)){
   if(version>Integer.MAX_VALUE-1||sequence>Integer.MAX_VALUE-1||sequence<1||generation<1)throw new Conflict("Departure counters lack receipt headroom");var token=h.path("departure_token");complete(token,"id","handoff_id","unit_id","run_id","epoch","custody_generation","last_sequence","unit_version");Policy.uuid(token.get("id"));
   for(var field:List.of("run_id","epoch"))if(!token.path(field).equals(h.path(field)))throw new Conflict("Departure token scope mismatch");for(var field:List.of("custody_generation","last_sequence"))if(!token.path(field).equals(unit.path(field)))throw new Conflict("Departure token sequence mismatch");
   if(!token.path("handoff_id").equals(h.path("id"))||!token.path("unit_id").equals(unit.path("id"))||!token.path("unit_version").equals(unit.path("version"))||!unit.path("state").asText().equals("in_transit")||!unit.path("position").isNull()||!unit.path("origin").equals(h.path("origin"))||!unit.path("destination").equals(h.path("destination"))||!unit.path("handoff_id").equals(h.path("id")))throw new Conflict("Departure requires matching unplaced source custody");if(state.equals("acknowledged"))Policy.uuid(h.get("receipt_id"));
  }else throw new IllegalArgumentException("Unsupported receiving custody transition");return (ObjectNode)h;
 }
 static String ingest(Store s,JsonNode event,String endpoint){var h=validate(event);var peer=s.settings.peers.path("materials");if(!s.settings.providers.path("materials").asText().equals("helics")||!peer.path("source").asText().equals("storage")||!peer.path("endpoint").asText().equals(endpoint)||!event.path("federation_id").asText().equals(s.settings.federation))throw new Conflict("Unconfigured custody peer");
  return s.tx(c->{var run=current(c);if(!event.path("run_id").asText().equals(run.get("id").toString())||!event.path("epoch").asText().equals(run.get("epoch").toString()))return "fenced";UUID eventId=Policy.uuid(event.get("event_id"));var old=one(c,"SELECT * FROM production_custody_events WHERE event_id=?",eventId);
   if(old!=null){if(!json(old.get("envelope")).equals(event))throw new Conflict("Custody event identity changed");if(Set.of("running","held").contains(run.get("state"))){sql(c,"UPDATE jobs SET status='pending',due_at=?,retry_after=clock_timestamp(),error=NULL WHERE id=? AND EXISTS(SELECT 1 FROM production_commands WHERE id=? AND retryable_capacity)",Math.max(number(run,"granted"),event.path("effective_time").asDouble()),old.get("command_id"),old.get("command_id"));sql(c,"UPDATE production_commands SET status='pending',reason=NULL,retryable_capacity=false WHERE id=? AND retryable_capacity",old.get("command_id"));sql(c,"UPDATE outbox SET retry_after=clock_timestamp() WHERE job_id=?",old.get("command_id"));replay(c,run,event);}return "duplicate";}
   if(!Set.of("running","held").contains(run.get("state")))throw new Conflict("Inactive receiving run");UUID id=UUID.randomUUID();double due=Math.max(number(run,"granted"),event.path("effective_time").asDouble());sql(c,"INSERT INTO jobs(id,run_id,epoch,idempotency_key,due_at,original_due_at,payload) VALUES (?,?,?,?,?,?,?::jsonb)",id,run.get("id"),run.get("epoch"),"boundary:"+eventId,due,event.path("effective_time").asDouble(),Json.write(Map.of("custody",event,"custody_endpoint",endpoint)));sql(c,"INSERT INTO production_commands(id,run_id,command) VALUES (?,?,?::jsonb)",id,run.get("id"),Json.write(Map.of("action","custody","handoff_id",h.path("id").asText())));sql(c,"INSERT INTO production_custody_events VALUES (?,?,?::jsonb,?)",eventId,run.get("id"),Json.write(event),id);return "accepted";
  });
 }
 static String execute(Store s,Connection c,Map<String,Object> run,Map<String,Object> job)throws SQLException{
  var event=json(job.get("payload")).path("custody");var save=c.setSavepoint();try{Production.ensure(c,run);apply(s,c,run,job,event);sql(c,"UPDATE production_commands SET status='completed',reason=NULL WHERE id=?",job.get("id"));}catch(Conflict|IllegalArgumentException|Capacity error){c.rollback(save);if(!(error instanceof Capacity))CustodyQuarantine.record(c,run,event,json(job.get("payload")).path("custody_endpoint").asText(),"apply",error.getMessage(),job.get("id"));sql(c,"UPDATE production_commands SET status='rejected',reason=?,retryable_capacity=? WHERE id=?",error.getMessage(),error instanceof Capacity,job.get("id"));}sql(c,"INSERT INTO inbox(event_id,run_id,epoch) VALUES (?,?,?) ON CONFLICT DO NOTHING",job.get("id"),run.get("id"),run.get("epoch"));sql(c,"UPDATE jobs SET status='completed',error=NULL WHERE id=?",job.get("id"));return "completed";
 }
 static void compatible(Connection c,Map<String,Object> run,JsonNode h)throws SQLException{
  String destination=h.path("destination").asText(),sku=h.path("unit").path("contents").get(0).path("sku").asText();var cfg=json(one(c,"SELECT config FROM production_config WHERE run_id=?",run.get("id")).get("config"));
  for(var line:cfg.path("lines"))if(destination.startsWith(HandlingUnits.cell(cfg,line.path("code").asText())+".input")){for(var product:cfg.path("products"))if(line.path("products").toString().contains("\""+product.path("sku").asText()+"\"")&&product.path("bom").has(sku))return;}
  throw new Conflict("Raw unit is incompatible with the configured receiving cell");
 }
 static void apply(Store s,Connection c,Map<String,Object> run,Map<String,Object> job,JsonNode event)throws SQLException{
  var h=validate(event);var unit=h.path("unit");UUID id=Policy.uuid(h.get("id"));var old=one(c,"SELECT * FROM production_custody WHERE id=?",id);if(old!=null&&!old.get("correlation_id").toString().equals(event.path("correlation_id").asText()))throw new Conflict("Handoff correlation changed");
  if(h.path("state").asText().equals("offered")){
   if(old!=null){if(!json(old.get("offer")).equals(h))throw new Conflict("Handoff identity changed");return;}
   MaterialPlans.checkOffer(c,run,event);compatible(c,run,h);if(one(c,"SELECT 1 FROM production_handling_units WHERE id=? UNION ALL SELECT 1 FROM production_custody WHERE unit_id=? AND state='accepted'",Policy.uuid(unit.get("id")),Policy.uuid(unit.get("id")))!=null)throw new Conflict("Barcode already known or accepted");
   if(one(c,"SELECT 1 FROM production_handling_units WHERE run_id=? AND epoch=? AND position=? UNION ALL SELECT 1 FROM production_custody WHERE run_id=? AND epoch=? AND destination=? AND state='accepted'",run.get("id"),run.get("epoch"),h.path("destination").asText(),run.get("id"),run.get("epoch"),h.path("destination").asText())!=null)throw new Capacity("Production input endpoint capacity unavailable; retry the identical offer after capacity frees");
   var accepted=h.deepCopy();accepted.put("state","accepted");sql(c,"INSERT INTO production_custody VALUES (?,?,?,?,?,?,'accepted',?::jsonb,?::jsonb,NULL,?)",id,run.get("id"),run.get("epoch"),Policy.uuid(unit.get("id")),h.path("destination").asText(),Policy.uuid(event.get("correlation_id")),Json.write(h),Json.write(accepted),job.get("id"));publish(s,c,run,event,accepted);return;
  }
  if(old==null)throw new Conflict("Departure requires durable capacity acceptance");var offer=json(old.get("offer"));for(var field:List.of("id","run_id","epoch","source","destination_owner","origin","destination"))if(!h.path(field).equals(offer.path(field)))throw new Conflict("Departure changed accepted custody");var expected=(ObjectNode)offer.path("unit").deepCopy();expected.put("state","in_transit");expected.putNull("position");expected.set("origin",h.get("origin"));expected.set("destination",h.get("destination"));expected.set("handoff_id",h.get("id"));for(var field:List.of("version","last_sequence","custody_generation"))expected.put(field,expected.path(field).asInt()+1);if(!expected.equals(unit))throw new Conflict("Departure changed immutable contents or skipped sequence");
  if(old.get("receipt")!=null){var receipt=json(old.get("receipt"));var check=h.deepCopy();check.put("state","received");check.set("receipt_id",receipt.get("receipt_id"));if(!check.equals(receipt)||h.path("state").asText().equals("acknowledged")&&!h.path("receipt_id").equals(receipt.path("receipt_id")))throw new Conflict("Conflicting receipt proof");if(h.path("state").asText().equals("acknowledged"))sql(c,"UPDATE production_custody SET state='acknowledged' WHERE id=?",id);return;}
  if(!h.path("state").asText().equals("departed"))throw new Conflict("Acknowledgement preceded receipt");compatible(c,run,h);String sku=unit.path("contents").get(0).path("sku").asText();int quantity=unit.path("contents").get(0).path("quantity").asInt();
  if(sql(c,"UPDATE production_materials SET quantity=quantity+? WHERE run_id=? AND sku=? AND quantity<=?",quantity,run.get("id"),sku,Integer.MAX_VALUE-quantity)!=1)throw new Capacity("Raw material ledger capacity unavailable");
  Object assigned=MaterialPlans.batch(c,run,Policy.uuid(unit.get("id")));sql(c,"INSERT INTO production_handling_units(id,barcode,run_id,epoch,sku,quantity,category,state,position,version,custody_generation,last_sequence,command_id,batch_id) VALUES (?,?,?,?,?,?,'raw',?,?,?,?,?,?,?)",Policy.uuid(unit.get("id")),unit.path("barcode").asText(),run.get("id"),run.get("epoch"),sku,quantity,assigned==null?"available":"reserved",h.path("destination").asText(),unit.path("version").asInt()+1,unit.path("custody_generation").asInt(),unit.path("last_sequence").asInt()+1,job.get("id"),assigned);
  var refs=new LinkedHashMap<String,Object>();refs.put("transfer_id",null);refs.put("batch_id",assigned);refs.put("shipment_id",null);sql(c,"INSERT INTO production_unit_movements(id,unit_id,barcode,run_id,epoch,sequence,custody_generation,action,origin,destination,simulation_time,\"references\") VALUES (?,?,?,?,?,?,?,'receive',?,?,?,?::jsonb)",uuid5(id,"receipt-movement"),Policy.uuid(unit.get("id")),unit.path("barcode").asText(),run.get("id"),run.get("epoch"),unit.path("last_sequence").asInt()+1,unit.path("custody_generation").asInt(),h.path("origin").asText(),h.path("destination").asText(),run.get("granted"),Json.write(refs));
  MaterialPlans.received(c,run,Policy.uuid(unit.get("id")));
  var receipt=h.deepCopy();receipt.put("state","received");receipt.put("receipt_id",uuid5(id,"manufacturing-receipt").toString());sql(c,"UPDATE production_custody SET state='received',receipt=?::jsonb WHERE id=?",Json.write(receipt),id);publish(s,c,run,event,receipt);
 }
 static void publish(Store s,Connection c,Map<String,Object> run,JsonNode incoming,JsonNode h)throws SQLException{UUID id=uuid5(Policy.uuid(h.get("id")),"manufacturing:"+h.path("state").asText());var e=Json.M.createObjectNode();e.put("schema_version","1.0");e.put("type","handling."+h.path("state").asText()+".v1");e.put("event_id",id.toString());e.put("federation_id",s.settings.federation);e.put("run_id",run.get("id").toString());e.put("epoch",run.get("epoch").toString());e.set("correlation_id",incoming.get("correlation_id"));e.set("causation_id",h.get("id"));e.set("aggregate_id",h.get("id"));e.put("aggregate_version",h.path("unit").path("version").asInt());e.put("source","manufacturing");e.put("destination","storage");e.put("boundary","requests");e.put("effective_time",number(run,"granted")+s.settings.quantum);e.put("wall_time",Instant.now().toString());e.put("quantity_unit","item");e.set("payload",h);sql(c,"INSERT INTO boundary_outbox(id,run_id,envelope) VALUES (?,?,?::jsonb) ON CONFLICT(id) DO NOTHING",id,run.get("id"),Json.write(e));}
 static List<JsonNode> snapshot(Connection c,Map<String,Object> run)throws SQLException{var result=new ArrayList<JsonNode>();for(var row:rows(c,"SELECT * FROM production_custody WHERE run_id=? AND epoch=? ORDER BY id",run.get("id"),run.get("epoch"))){var h=(ObjectNode)json(row.get(row.get("receipt")==null?"acceptance":"receipt")).deepCopy();h.put("state",row.get("state").toString());result.add(h);}return result;}
 static void replay(Connection c,Map<String,Object> run,JsonNode event)throws SQLException{String stage=switch(event.path("type").asText()){case "handling.offered.v1"->"accepted";case "handling.departed.v1"->"received";default->null;};if(stage==null)return;UUID eventId=uuid5(Policy.uuid(event.get("aggregate_id")),"manufacturing:"+stage);var old=one(c,"SELECT envelope FROM boundary_outbox b WHERE b.run_id=? AND b.envelope->>'event_id'=? AND NOT EXISTS(SELECT 1 FROM boundary_outbox n WHERE n.run_id=b.run_id AND n.envelope->>'event_id'=b.envelope->>'event_id' AND (n.sent_at IS NULL OR n.sent_at>clock_timestamp()-interval '5 seconds')) LIMIT 1",run.get("id"),eventId.toString());if(old!=null)sql(c,"INSERT INTO boundary_outbox(id,run_id,envelope) VALUES (?,?,?::jsonb)",UUID.randomUUID(),run.get("id"),Json.write(old.get("envelope")));}
 static int recover(Connection c,Map<String,Object> run)throws SQLException{
  if(!Set.of("running","held").contains(run.get("state")))return 0;
  var pending=rows(c,"SELECT DISTINCT b.envelope FROM boundary_outbox b JOIN production_custody h ON h.id::text=b.envelope->'payload'->>'id' AND h.state=b.envelope->'payload'->>'state' WHERE h.run_id=? AND h.epoch=? AND h.state IN ('accepted','received') AND b.run_id=? AND NOT EXISTS(SELECT 1 FROM boundary_outbox n WHERE n.run_id=b.run_id AND n.envelope->>'event_id'=b.envelope->>'event_id' AND (n.sent_at IS NULL OR n.sent_at>clock_timestamp()-interval '5 seconds'))",run.get("id"),run.get("epoch"),run.get("id"));
  for(var row:pending)sql(c,"INSERT INTO boundary_outbox(id,run_id,envelope) VALUES (?,?,?::jsonb)",UUID.randomUUID(),run.get("id"),Json.write(row.get("envelope")));return pending.size();
 }

}
